using System;using System.Linq;using System.IO;using System.Reflection;using System.Collections.Generic;using System.Globalization;using System.Windows.Forms;using BeamScheduleFormatter;
class WorkspaceInputsUiTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static T Get<T>(object o,string field){return (T)o.GetType().GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static object Call(object o,string method,params object[] args){return o.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(o,args);}
 [STAThread]static void Main(){Application.EnableVisualStyles();AccessCodes.Granted=true;string dir=Path.Combine(Path.GetTempPath(),"DTCE-manual-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{string path=Path.Combine(dir,"Manual.pow.xml");var groups=Enumerable.Range(0,9).Select(n=>new[]{"","Spacing (mm)",""}).ToArray();groups[0]=new[]{"12","Spacing (mm)","150"};groups[2]=new[]{"16","Number of bars","9"};var manual=ManualSlabSchedule.Create("MANUAL-S1","125",groups);using(var form=new ProgramOfWorksForm()){var slab=Get<SlabEstimatorForm>(form,"slab");Call(slab,"AddSource",ManualSlabSchedule.Write(manual),"Manual MANUAL-S1.xml");var grid=slab.WorksInputGrid;int n=grid.Rows.Add();var row=grid.Rows[n];row.Cells[0].Value="Manual room";row.Cells[1].Value=manual.Mark;row.Cells[2].Value="3";row.Cells[3].Value="4";row.Cells[4].Value="2";row.Cells[5].Value="Elevated";Call(slab,"SetSupportDefaults",row);slab.Recalculate();Check(row.Tag is SlabTakeoff&&Math.Abs(((SlabTakeoff)row.Tag).Measures.ConcreteTotal-3)<1e-8,"Manual-only slab quantities work without any DXF");Check(slab.sourceAttachments.Files.Count==0,"Manual input is a saved schedule, not mislabeled as an uploaded DXF");foreach(var f in new Form[]{Get<EstimatorForm>(form,"beam"),slab}){var navigation=f.Controls.OfType<TabControl>().Single();Check(navigation.Dock==DockStyle.Fill&&navigation.Alignment==TabAlignment.Top&&navigation.TabPages[0].Text=="Measurements","Embedded RC measurements and summaries share full-height top tabs");}foreach(var field in new[]{"footings","rcWalls","canopies"})Check(Get<DataGridView>(form,field).ScrollBars==ScrollBars.Both,"RC grid scrolling is consistent for "+field);var boq=Get<DataGridView>(form,"boqGrid");boq.Rows.Clear();int b=boq.Rows.Add("900(1)d","Test",30.7027,"m3");Check(Convert.ToString(boq.Rows[b].Cells[2].FormattedValue)=="30.70"&&Convert.ToDouble(boq.Rows[b].Cells[2].Value)==30.7027,"BOQ shows two decimals while preserving stored precision");var summary=Get<Label>(form,"excelConnectionSummary");Check(summary.Text=="Excel: not linked"&&summary.Parent.Name=="ExcelStatusBar","Persistent workbook identity is in the bottom status bar");form.SaveTo(path);}
 using(var form=new ProgramOfWorksForm()){form.OpenFrom(path);var slab=Get<SlabEstimatorForm>(form,"slab");var result=(SlabTakeoff)slab.WorksInputGrid.Rows[0].Tag;Check(result!=null&&result.Schedule.Manual&&result.Schedule.Bars[2].ExplicitCount==9,"Manual reinforcement/count survives full POW save/open");var angles=Get<DataGridView>(form,"steelAngles");int n=angles.Rows.Add();angles.Rows[n].Cells[0].Value="TC";angles.Rows[n].Cells[1].Value="Truss 1";angles.Rows[n].Cells[2].Value="L75x75x5mm (PNS)";angles.Rows[n].Cells[3].Value="A36";angles.Rows[n].Cells[4].Value="10.322";angles.Rows[n].Cells[5].Value="2";Call(form,"Recalculate");Check(angles.Rows[n].Tag is SteelCutDemand&&Convert.ToString(angles.Rows[n].Cells[8].Value).StartsWith("Segmented purchase"),"Long angle row reaches purchase plan instead of old 6m error");Check(Convert.ToDouble(angles.Rows[n].Cells[7].Value)>0,"Angle row receives combined segment stock purchase weight");}
 using(var form=new Form())using(var combo=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=400}){combo.Items.Add("L75x75x5mm (PNS) — complete selected profile");combo.SelectedIndex=0;form.Controls.Add(combo);PowTheme.Apply(form);form.Show();Application.DoEvents();string selected=combo.Text;DropdownCopy.Copy(combo);Check(Clipboard.GetText()==selected&&combo.Text==selected,"Full dropdown value can be copied without changing selection");}
 Console.WriteLine("PASS: "+checks+" native RC layout, manual POW persistence, BOQ precision, angle rows and profile copy checks");}finally{Directory.Delete(dir,true);}}
}
